const r = await tools.exec_command({
  cmd: "rg -n \"database:\" node_modules/better-auth/dist -g '*.d.mts' | head -50\nrg -n \"betterSqlite3\" node_modules/better-auth node_modules/@better-auth -g '*.d.mts' -g '*.mjs' | head -50\nfind node_modules/better-auth -maxdepth 2 -type f -iname '*schema*' | head",
  workdir: "/work",
  yield_time_ms: 10000,
  max_output_tokens: 10000
});
text(r.output);

