  cmd: "rg -n \"BetterAuthOptions\" node_modules/@better-auth/core -g '*.d.mts' | head -30\nrg -n \"database\" node_modules/@better-auth/core/dist/types -g '*.d.mts' | head -50",
  workdir: "/work",
  yield_time_ms: 10000,
  max_output_tokens: 10000
});
text(r.output);

