export function EditBookmarkDialog({bookmark,folders,tags,onCancel,onSaved}:{bookmark:Bookmark;folders:Folder[];tags:Tag[];onCancel:()=>void;onSaved:(value:Bookmark)=>void}){const [url,setUrl]=useState(bookmark.url);const[title,setTitle]=useState(bookmark.title);const[notes,setNotes]=useState(bookmark.notes??"");const[folderId,setFolderId]=useState(bookmark.folder?.id.toString()??"");const[tagIds,setTagIds]=useState(bookmark.tags.map((tag)=>tag.id));const[error,setError]=useState("");const[busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{onSaved(await bookmarkApi.update(bookmark.id,{url,title,notes:notes||null,folderId:folderId?Number(folderId):null,tagIds}));}catch(reason){setError(reason instanceof Error?reason.message:"Changes weren’t saved.");setBusy(false);}}return <div className="modal-backdrop"><section className="modal edit-modal" role="dialog" aria-modal="true" aria-labelledby="edit-title"><h2 id="edit-title">Edit bookmark</h2><form onSubmit={(e)=>void submit(e)}><label>Title<input autoFocus value={title} onChange={(e)=>setTitle(e.target.value)} maxLength={300} required/></label><label>Web address<input type="url" value={url} onChange={(e)=>setUrl(e.target.value)} required/></label><label>Notes<textarea value={notes} onChange={(e)=>setNotes(e.target.value)} maxLength={10000}/></label><label>Folder<select value={folderId} onChange={(e)=>setFolderId(e.target.value)}><option value="">No folder</option>{folders.map((folder)=><option key={folder.id} value={folder.id}>{folder.name}</option>)}</select></label><fieldset><legend>Tags</legend><div className="tag-picker">{tags.map((tag)=><label className="check-chip" key={tag.id}><input type="checkbox" checked={tagIds.includes(tag.id)} onChange={()=>setTagIds((ids)=>ids.includes(tag.id)?ids.filter((id)=>id!==tag.id):[...ids,tag.id])}/>{tag.name}</label>)}</div></fieldset>{error&&<p className="form-error" role="alert">{error}</p>}<div className="dialog-actions"><button type="button" onClick={onCancel}>Cancel</button><button className="primary" disabled={busy}>{busy?"Saving…":"Save changes"}</button></div></form></section></div>}

