import { useState } from "react";
import type { Folder,Tag } from "../../../shared/contracts/organization.js";
import { organizationApi } from "./organization-api.js";

export function ManageOrganizationDialog({kind,items,onClose,onChanged}:{kind:"folders"|"tags";items:Array<Folder|Tag>;onClose:()=>void;onChanged:()=>Promise<void>}){const[name,setName]=useState("");const[error,setError]=useState("");const[editing,setEditing]=useState<number>();async function save(){if(!name.trim())return;setError("");try{if(editing)await organizationApi.rename(kind,editing,name);else await organizationApi.create(kind,name);setName("");setEditing(undefined);await onChanged();}catch(reason){setError(reason instanceof Error?reason.message:"That change could not be saved.");}}async function remove(item:Folder|Tag){if(!confirm(`Delete “${item.name}”? Bookmarks will be kept.`))return;try{await organizationApi.remove(kind,item.id);await onChanged();}catch(reason){setError(reason instanceof Error?reason.message:"Could not delete it.");}}return <div className="modal-backdrop"><section className="modal manage-modal" role="dialog" aria-modal="true" aria-labelledby="manage-title"><h2 id="manage-title">Manage {kind}</h2><p className="muted">Deleting a {kind==="folders"?"folder":"tag"} never deletes its bookmarks.</p><div className="inline-create"><input autoFocus value={name} onChange={(e)=>setName(e.target.value)} placeholder={editing?"New name":`New ${kind==="folders"?"folder":"tag"} name`} maxLength={kind==="folders"?80:50}/><button className="primary" onClick={()=>void save()}>{editing?"Rename":"Add"}</button></div>{error&&<p className="form-error" role="alert">{error}</p>}<ul className="manage-list">{items.map((item)=><li key={item.id}><span><strong>{item.name}</strong><small>{item.count} bookmark{item.count===1?"":"s"}</small></span><span><button aria-label={`Rename ${item.name}`} onClick={()=>{setEditing(item.id);setName(item.name);}}>✎</button><button aria-label={`Delete ${item.name}`} onClick={()=>void remove(item)}>⌫</button></span></li>)}</ul><div className="dialog-actions"><button onClick={onClose}>Done</button></div></section></div>}

