import { useState } from "react";
import type { Folder,Tag } from "../../../shared/contracts/organization.js";
import type { LibraryQuery } from "../bookmarks/useLibraryQuery.js";
import { ManageOrganizationDialog } from "./ManageOrganizationDialog.js";

export function OrganizationSidebar({folders,tags,total,query,setQuery,onRefresh}:{folders:Folder[];tags:Tag[];total:number;query:LibraryQuery;setQuery:(patch:Partial<LibraryQuery>)=>void;onRefresh:()=>Promise<void>}){const[manage,setManage]=useState<"folders"|"tags">();return <aside className="sidebar"><nav aria-label="Library views"><button className={!query.folderId&&!query.tagId&&!query.favorite?"active":""} onClick={()=>setQuery({folderId:"",tagId:"",favorite:false})}><span>⌂ All bookmarks</span><b>{total}</b></button><button className={query.favorite?"active":""} onClick={()=>setQuery({favorite:!query.favorite})}><span>☆ Favorites</span></button></nav><div className="sidebar-section"><div className="sidebar-heading"><span>FOLDERS</span><button aria-label="Manage folders" onClick={()=>setManage("folders")}>＋</button></div>{folders.length===0?<p className="sidebar-empty">No folders yet</p>:folders.map((folder)=><button key={folder.id} className={query.folderId===String(folder.id)?"active":""} onClick={()=>setQuery({folderId:query.folderId===String(folder.id)?"":String(folder.id)})}><span>▰ {folder.name}</span><b>{folder.count}</b></button>)}</div><div className="sidebar-section"><div className="sidebar-heading"><span>TAGS</span><button aria-label="Manage tags" onClick={()=>setManage("tags")}>＋</button></div><div className="sidebar-tags">{tags.length===0?<p className="sidebar-empty">No tags yet</p>:tags.map((tag)=><button key={tag.id} className={query.tagId===String(tag.id)?"active":""} onClick={()=>setQuery({tagId:query.tagId===String(tag.id)?"":String(tag.id)})}>#{tag.name} <b>{tag.count}</b></button>)}</div></div>{manage&&<ManageOrganizationDialog kind={manage} items={manage==="folders"?folders:tags} onClose={()=>setManage(undefined)} onChanged={onRefresh}/>}</aside>}

