import type { Folder,Tag } from "../../../shared/contracts/organization.js";
import type { LibraryQuery } from "./useLibraryQuery.js";
export function LibraryControls({query,setQuery,clear,folders,tags,total}:{query:LibraryQuery;setQuery:(patch:Partial<LibraryQuery>)=>void;clear:()=>void;folders:Folder[];tags:Tag[];total:number}){const active=Boolean(query.q||query.folderId||query.tagId||query.favorite);return <div className="library-controls"><div className="search-box"><span>⌕</span><input aria-label="Search bookmarks" placeholder="Search by title, address, or tag…" value={query.q} onChange={(e)=>setQuery({q:e.target.value})}/><kbd>⌘ K</kbd></div><select aria-label="Sort bookmarks" value={query.sort} onChange={(e)=>setQuery({sort:e.target.value as LibraryQuery["sort"]})}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="title">Title A–Z</option></select><div className="result-count">{total} {total===1?"bookmark":"bookmarks"}</div>{active&&<div className="active-filters" aria-label="Active filters">{query.q&&<button onClick={()=>setQuery({q:""})}>Search: {query.q} ×</button>}{query.folderId&&<button onClick={()=>setQuery({folderId:""})}>Folder: {folders.find((f)=>String(f.id)===query.folderId)?.name} ×</button>}{query.tagId&&<button onClick={()=>setQuery({tagId:""})}>Tag: {tags.find((t)=>String(t.id)===query.tagId)?.name} ×</button>}{query.favorite&&<button onClick={()=>setQuery({favorite:false})}>Favorites ×</button>}<button className="clear" onClick={clear}>Clear all</button></div>}</div>}

